  "Aucun joueur ne vous est attribué pour l'instant : le sélectionneur, un adjoint ou un recruteur vous en confiera.": "Ainda não há jogadores atribuídos a você: o selecionador, um adjunto ou um recrutador vai atribuí-los.",
  "Vous ne voyez que les joueurs qui vous sont attribués.": "Você só vê os jogadores atribuídos a você.",
  "Caractéristiques et état physique : visibles du staff de la sélection seulement, jamais le salaire, le contrat ni le potentiel.": "Atributos e condição física: visíveis só para a equipe da seleção, nunca o salário, o contrato nem o potencial.",
  "Mêmes accès que le sélectionneur (joueurs, convocations, ordres, amicaux, staff), sauf nommer ou retirer un adjoint.": "Mesmos acessos do selecionador (jogadores, convocações, ordens, amistosos, equipe), exceto nomear ou remover um adjunto.",
  "Aident aux décisions de roster et d'ordres : consultent les joueurs, la présélection, les convoqués et la tactique, et suivent des joueurs.": "Ajudam nas decisões de elenco e ordens: consultam jogadores, pré-seleção, convocados e tática, e acompanham jogadores.",
  "Gèrent les joueurs suivis, nomment les scouts et leur attribuent des joueurs.": "Gerenciam os jogadores acompanhados, nomeiam olheiros e lhes atribuem jogadores.",
  "Ne voient que les joueurs qui leur sont attribués : ils les suivent et les analysent.": "Só veem os jogadores atribuídos a eles: acompanham e analisam.",
  "Adjoint : mêmes accès que le sélectionneur, sauf la nomination des adjoints.": "Adjunto: mesmos acessos do selecionador, exceto nomear adjuntos.",
  "Personne aidante : aide aux décisions de roster et d'ordres (consultation).": "Colaborador: ajuda nas decisões de elenco e ordens (consulta).",
  "Recruteur (DTN) : joueurs suivis, nomination des scouts et attribution de leurs joueurs.": "Recrutador (direção técnica): jogadores acompanhados, nomeação de olheiros e atribuição dos seus jogadores.",
  "Scout (DTN) : suit et analyse les joueurs qui lui sont attribués.": "Olheiro (direção técnica): acompanha e analisa os jogadores atribuídos.",
  "Rôle inconnu (adjoint, personne aidante, recruteur ou scout).": "Função desconhecida (adjunto, colaborador, recrutador ou olheiro).",
  "Seul le sélectionneur nomme ses adjoints.": "Só o selecionador nomeia seus adjuntos.",
