  "Pas encore de légende : un joueur le devient par sa carrière au club (matchs, points, saisons, titres, distinctions, formation au club).": "Ainda não há lendas: um jogador se torna uma pela carreira no clube (jogos, pontos, temporadas, títulos, prêmios, formação no clube).",
