  "Aucun analyste": "Nenhum analista",
  "Une analyse par adversaire et par saison (une nouvelle équipe par jour). Les estimations ne sont jamais certaines et perdent en fiabilité avec le temps.": "Uma análise por adversário e por temporada (uma equipe nova por dia). As estimativas nunca são certas e perdem confiabilidade com o tempo.",
  "Nom, poste et taille des joueurs adverses sont toujours visibles ; leur salaire n'est qu'une fourchette et aucune de leurs valeurs n'est jamais exacte. Recrutez un": "Nome, posição e altura dos jogadores adversários estão sempre visíveis; o salário deles é apenas uma faixa e nenhum dos seus valores é exato. Contrate um",
  "(onglet Staff) pour faire une séance vidéo sur un adversaire (une par jour, une fois par adversaire et par saison) : elle estime une partie des caractéristiques de tout son effectif sous forme de fourchettes, plus nombreuses et plus étroites selon le niveau de l'analyste, avec un niveau de confiance. Une estimation peut se tromper, et un ancien rapport perd en fiabilité d'une saison à l'autre. L'": "(aba Staff) para fazer uma sessão de vídeo sobre um adversário (uma por dia, uma vez por adversário e por temporada): ela estima parte dos atributos de todo o elenco dele em forma de faixas, mais numerosas e mais estreitas conforme o nível do analista, com um nível de confiança. Uma estimativa pode errar, e um relatório antigo perde confiabilidade de uma temporada para outra. A ",
