  "Aucun rapport de l'analyste vidéo.": "Nenhum relatório do analista de vídeo.",
  "Aucune caractéristique de cet effectif n'a encore été estimée. Une séance vidéo estime des caractéristiques de TOUS ses joueurs, une fois par saison : plus votre analyste est bon, plus elle en estime et plus les fourchettes sont étroites. Une estimation n'est jamais certaine.": "Nenhum atributo deste elenco foi estimado ainda. Uma sessão de vídeo estima atributos de TODOS os seus jogadores, uma vez por temporada: quanto melhor o seu analista, mais ela estima e mais estreitas são as faixas. Uma estimativa nunca é certa.",
