  "Liste figée 3 jours avant le premier match : seul un joueur blessé ou devenu inéligible peut être remplacé. Pour chaque match, 12 joueurs sont choisis parmi ces 15 dans Tactique.": "Lista fechada 3 dias antes do primeiro jogo: só um jogador lesionado ou que deixou de ser elegível pode ser substituído. Para cada jogo, 12 destes 15 jogadores são escolhidos em Tática.",
