  "Votre sélection joue ses qualifications à chaque fenêtre restante. Les amicaux se jouent uniquement pendant les fenêtres internationales (dimanche à 20h), entre deux sélections sans match de qualification ce jour-là. Réponse attendue avant le gel des convocations (3 jours avant le match).": "Sua seleção joga eliminatórias em cada janela restante. Os amistosos só são jogados nas janelas internacionais (domingo às 20h), entre duas seleções sem jogo de eliminatórias nesse dia. Resposta esperada antes do fecho das convocações (3 dias antes do jogo).",
