  "Victoire 2 points, défaite 1. Départage : confrontations directes, différence de points, points marqués. Phase finale : les 2 premiers de chaque groupe et les 2 meilleurs troisièmes ; les autres jouent le tournoi de consolation.": "Vitória 2 pontos, derrota 1. Desempate: confronto direto, saldo de pontos, pontos marcados. Fase final: os 2 primeiros de cada grupo e os 2 melhores terceiros; os demais disputam o torneio de consolação.",
  "Victoire 2 points, défaite 1. Départage : confrontations directes, différence de points, points marqués. Toutes les sélections du continent vont en phase finale ; le classement donne les têtes de série.": "Vitória 2 pontos, derrota 1. Desempate: confronto direto, saldo de pontos, pontos marcados. Todas as seleções do continente vão à fase final; a classificação define os cabeças de chave.",
  "Victoire 2 points, défaite 1. Départage : confrontations directes, différence de points, points marqués. Le classement fixe les têtes de série de la Coupe du monde et du tournoi de consolation.": "Vitória 2 pontos, derrota 1. Desempate: confronto direto, saldo de pontos, pontos marcados. A classificação define os cabeças de chave da Copa do Mundo e do torneio de consolação.",
  "Victoire 2 points, défaite 1. Départage : confrontations directes, différence de points, points marqués.": "Vitória 2 pontos, derrota 1. Desempate: confronto direto, saldo de pontos, pontos marcados.",
