  ": parquet aux couleurs du club dans le direct quand vous recevez et salle personnalisée (couleurs, façade, toit, ambiance) dans l'onglet Personnalisation, sous le Guide, avec le logo, les maillots, le trigramme et le nom de la salle ; apparence des jeunes de l'académie (bouton « Personnaliser l'apparence » sur leur carte) et des joueurs qu'elle a formés, et numéro de maillot de chaque joueur (carte « Personnalisation » de leur fiche). Tous les joueurs ont un numéro, visible sur leur fiche ; les numéros retirés au Hall of Fame ne sont plus portés.": ": quadra com as cores do clube no jogo ao vivo quando você joga em casa e ginásio personalizado (cores, fachada, telhado, ambiente) na aba Personalização, abaixo do Guia, com o escudo, os uniformes, a sigla e o nome do ginásio; aparência dos jovens da academia (botão “Personalizar aparência” no card deles) e dos jogadores formados por ela, e número da camisa de cada jogador (card “Personalização” da ficha deles). Todos os jogadores têm um número, visível na ficha; os números aposentados no Hall of Fame não são mais usados.",
