  "Aucun manager classé pour l'instant : il faut un premier match officiel entre deux managers.": "Nenhum técnico ranqueado ainda: é preciso um primeiro jogo oficial entre dois técnicos.",
  "Votre note :": "Sua nota:",
  ". Vous serez classé après votre premier match officiel contre un autre manager.": ". Você será ranqueado após seu primeiro jogo oficial contra outro técnico.",
  "{0} · {1} match": "{0} · {1} jogo",
  "{0} · {1} matchs": "{0} · {1} jogos",
  "Note de départ 1500, qui monte ou descend à chaque match officiel contre un autre manager (plus l'adversaire est bien noté, plus la victoire rapporte). Les matchs contre l'IA et les amicaux ne comptent pas. {0} manager classé.": "Nota inicial 1500, que sobe ou desce a cada jogo oficial contra outro técnico (quanto mais bem avaliado o adversário, mais a vitória rende). Jogos contra a IA e amistosos não contam. {0} técnico ranqueado.",
  "Note de départ 1500, qui monte ou descend à chaque match officiel contre un autre manager (plus l'adversaire est bien noté, plus la victoire rapporte). Les matchs contre l'IA et les amicaux ne comptent pas. {0} managers classés.": "Nota inicial 1500, que sobe ou desce a cada jogo oficial contra outro técnico (quanto mais bem avaliado o adversário, mais a vitória rende). Jogos contra a IA e amistosos não contam. {0} técnicos ranqueados.",
  "Le classement se départage par victoires puis par différence de points. Places 1 à 4 : play-offs. Barrage et relégation seulement s'il existe un championnat juste en dessous (couleurs et légende l'indiquent). Ce panneau résume votre position et l'écart avec les places clés.": "A classificação é desempatada por vitórias e depois por saldo de pontos. Posições 1 a 4: playoffs. Repescagem e rebaixamento só se houver um campeonato logo abaixo (cores e legenda indicam). Este painel resume sua posição e a diferença para as posições-chave.",
  " ; s'il existe un championnat ouvert juste en dessous, le 10e est ": "; se houver um campeonato aberto logo abaixo, o 10º é ",
  "relégué": "rebaixado",
  ", puis le 9e, et avec trois championnats en dessous le 7e et le 8e jouent un ": ", depois o 9º, e com três campeonatos abaixo o 7º e o 8º disputam uma ",
  ". Seules les zones réellement en jeu sont colorées. Chaque équipe affiche sa forme récente. Un panneau \"course aux play-offs\" résume votre position, votre bilan et l'écart avec les places clés.": ". Só as zonas realmente em jogo são coloridas. Cada equipe mostra sua fase recente. Um painel \"corrida pelos playoffs\" resume sua posição, sua campanha e a diferença para as posições-chave.",
  "Play-offs · le champion monte": "Playoffs · o campeão sobe",
  "Play-offs · le champion monte en {0}": "Playoffs · o campeão sobe para a {0}",
  "Relégation directe (10e)": "Rebaixamento direto (10º)",
