  ", 5 et 6 maintien direct, 7 et 8": ", 5 e 6 permanência direta, 7 e 8",
  ", agrandissable palier par palier depuis cet onglet, accélère cette progression. À ses 18 ans, une décision est requise pour chaque jeune : le promouvoir dans l'effectif pro (il dévoile alors son vrai palier de potentiel) ou le libérer définitivement. Sans décision avant la saison suivante, il est automatiquement libéré. L'historique des jeunes promus reste visible en bas de la page.": ", ampliável nível por nível a partir desta aba, acelera essa evolução. Aos 18 anos, é preciso tomar uma decisão sobre cada jovem: promovê-lo ao elenco profissional (ele então revela seu verdadeiro nível de potencial) ou liberá-lo definitivamente. Sem decisão antes da temporada seguinte, ele é liberado automaticamente. O histórico dos jovens promovidos continua visível no fim da página.",
  ", au moment où commence l'émission d'avant-match.": ", no momento em que começa o programa pré-jogo.",
  "d'abord (liseré orange et petit « 5 »), puis la rotation, puis la réserve (nom estompé), d'après la feuille de match actuelle ; cliquez un titre de colonne pour trier toute la liste. Pour chacun : poste, potentiel, âge, taille, salaire, forme, motivation et évaluation des derniers matchs. Le menu": "primeiro (contorno laranja e pequeno “5”), depois a rotação, depois a reserva (nome esmaecido), de acordo com a escalação atual; clique no título de uma coluna para ordenar toda a lista. Para cada um: posição, potencial, idade, altura, salário, forma, motivação e avaliação dos últimos jogos. O menu",
  ", de plus en plus vite si vous la gardez plusieurs matchs de suite : +6, +8, +10, puis +12 par match. L'entraînement collectif": ", cada vez mais rápido se você a mantiver por vários jogos seguidos: +6, +8, +10 e depois +12 por jogo. O treino coletivo",
  ", du plus modeste au plus rare :": ", do mais modesto ao mais raro:",
  ", gérer l'": ", gerenciar o ",
  ", le {0}": ", em {0}",
  ", mais doucement : rien les 2 premiers matchs d'absence, puis -2, -4 et au maximum -6 par match. Revenir à une tactique délaissée la fait remonter progressivement, jamais d'un coup.": ", mas devagar: nada nos 2 primeiros jogos de ausência, depois -2, -4 e no máximo -6 por jogo. Voltar a uma tática deixada de lado a faz subir aos poucos, nunca de uma vez.",
  ", mais ils le prennent moins que d'autres zones.": ", mas eles o fazem menos do que em outras zonas.",
  ", Mécontents": ", Insatisfeitos",
  ", plus floue, alignée sur les mêmes paliers :": ", mais vaga, alinhada aos mesmos níveis:",
