  "\"Ça fait des semaines que je suis sur le banc sans la moindre explication, je demande à partir\", lâche {player}.": "\"Faz semanas que estou no banco sem a menor explicação, peço para sair\", dispara {player}.",
  "\"J'ai besoin de retrouver du temps de jeu ailleurs\", déclare {player}, visiblement lassé de la situation.": "\"Preciso voltar a ter minutos em outro lugar\", declara {player}, visivelmente cansado da situação.",
  "\"Je ne me sens plus utile ici, il est temps d'envisager un nouveau projet\", confie {player} à la presse.": "\"Não me sinto mais útil aqui, é hora de pensar em um novo projeto\", confidencia {player} à imprensa.",
  "\"Le club connaît ma position, je souhaite être transféré au plus vite\", affirme {player}.": "\"O clube conhece minha posição, quero ser transferido o quanto antes\", afirma {player}.",
  "« À mi-parcours, cette victoire contre Adversaire test confirme qu'on est sur la bonne trajectoire, il reste encore la moitié de la saison pour la confirmer. On va continuer à travailler dans la continuité, avec quelques ajustements tactiques pour la seconde moitié. »": "“Na metade do caminho, esta vitória contra Adversário teste confirma que estamos na trajetória certa, ainda resta metade da temporada para confirmar isso. Vamos continuar trabalhando com consistência, com alguns ajustes táticos para a segunda metade.”",
  "« Comme l'appareil » suit le mode clair ou sombre de ton ordinateur ou de ton téléphone.": "“Igual ao dispositivo” segue o modo claro ou escuro do seu computador ou do seu celular.",
  "({0}-{1}, en cours)": "({0}-{1}, em andamento)",
  "({1} pts) et": "({1} pts) e",
  "({1}) · {2} d'efficacité sur {3}": "({1}) · {2} de eficiência em {3}",
  "({3} pts).": "({3} pts).",
  "(aux deux niveaux) : Standard garde le comportement habituel. Adaptatif ajoute un vrai garbage time dès 10 points d'écart à partir du 3e quart-temps (au 4e quart-temps, à 18 points d'écart, les titulaires sortent pour ménager leur forme), et accélère légèrement le rythme dans les 5 dernières minutes d'un match serré.": "(nos dois níveis): Padrão mantém o comportamento habitual. Adaptativo adiciona um verdadeiro garbage time a partir de 10 pontos de diferença desde o 3º quarto (no 4º quarto, com 18 pontos de diferença, os titulares saem para poupar a forma), e acelera levemente o ritmo nos 5 últimos minutos de um jogo equilibrado.",
  "(avec une petite jauge à 10 crans dans l'Effectif ; survolez le nom du palier pour voir son rang de 1 à 10). Un jeune joueur encore faible mais à fort potentiel peut, bien entraîné, dépasser largement un joueur déjà bon dont le potentiel est presque atteint.": "(com um pequeno medidor de 10 níveis no Elenco; passe o mouse sobre o nome do nível para ver sua posição de 1 a 10). Um jogador jovem ainda fraco, mas com alto potencial, pode, bem treinado, superar de longe um jogador já bom cujo potencial está quase atingido.",
  "(c'est vous !)": "(é você!)",
  "(cinq moments clés de la saison : début, mi-saison, fin de saison régulière, demi-finale puis finale des play-offs). Chaque interview pose deux questions, avec un ton à choisir pour chacune : Agressif amplifie le résultat (meilleur gain en cas de victoire, pire perte en cas de défaite), Mesuré reste sûr et modéré, Humble plafonne le gain en cas de victoire mais est le seul ton qui tourne une défaite en effet positif. Toute l'équipe est concernée. Ignorer l'interview (possible pendant 3 jours) n'a aucun effet. Un remplaçant qui ne joue quasiment jamais perd un peu de motivation chaque semaine, davantage s'il est meilleur que le titulaire de son poste.": "(cinco momentos-chave da temporada: início, meio da temporada, fim da temporada regular, semifinal e depois final dos playoffs). Cada entrevista faz duas perguntas, com um tom a escolher para cada uma: Agressivo amplifica o resultado (maior ganho em caso de vitória, maior perda em caso de derrota), Moderado é seguro e comedido, Humilde limita o ganho em caso de vitória, mas é o único tom que transforma uma derrota em efeito positivo. A equipe inteira é afetada. Ignorar a entrevista (possível durante 3 dias) não tem nenhum efeito. Um reserva que quase nunca joga perde um pouco de motivação toda semana, mais ainda se for melhor que o titular da posição dele.",
  "(display-mode: standalone)": "(display-mode: standalone)",
