  "29 caractéristiques (0 à 99) : Tir à mi-distance, Tir à 3 points, Jeu intérieur, Passe, Rebond, Contre, Dribble, Agilité, Défense extérieure, Défense intérieure, Mental, Endurance, Lancer franc, Pénétration, Création de tir, Interceptions, Puissance, Concentration, Anticipation, Leadership, Vitesse, Accélération, Force, Détente, Décision, Sang-froid, Détermination, Discipline et Vision. Sur chacune, plus le chiffre est élevé, mieux c'est, sans exception. La couleur donne le niveau en un coup d'œil : rouge en dessous de 45, grise de 45 à 64, verte de 65 à 79, dorée à partir de 80 (niveau élite).": "29 atributos (0 a 99): Arremesso de meia distância, Arremesso de 3 pontos, Jogo interior, Passe, Rebote, Toco, Drible, Agilidade, Defesa exterior, Defesa interior, Mental, Resistência, Lance livre, Infiltração, Criação de arremesso, Roubos de bola, Potência, Concentração, Antecipação, Liderança, Velocidade, Aceleração, Força, Impulsão, Decisão, Sangue-frio, Determinação, Disciplina e Visão. Em todos eles, quanto maior o número, melhor, sem exceção. A cor indica o nível num piscar de olhos: vermelho abaixo de 45, cinza de 45 a 64, verde de 65 a 79, dourado a partir de 80 (nível elite).",
