  "5 paliers, du plus frais (90-100) au plus épuisé (0-39, risque de blessure nettement accru). Baisse après chaque match selon le temps de jeu, remonte de 10 points par jour sans match (15 avec l'entraînement collectif Récupération).": "5 níveis, do mais descansado (90-100) ao mais exausto (0-39, risco de lesão bem maior). Cai após cada jogo conforme o tempo em quadra, sobe 10 pontos por dia sem jogo (15 com o treino coletivo Recuperação).",
