  "Agrandissement du Centre de formation refusé.": "Ampliação do Centro de formação recusada.",
  "Agrandissez votre salle place par place pour accueillir plus de spectateurs (brique Agrandir la salle : chaque catégorie de places a son prix par place et son nombre maximum de places), et réglez le prix du billet CATÉGORIE PAR CATÉGORIE : Tribune Supérieure, Tribune Centrale, Courtside et Loges VIP n'ont ni la même capacité, ni la même tolérance au prix. Seuls les matchs à domicile rapportent une recette. L'humeur des supporters influence le remplissage et la tolérance au prix. D'autres infrastructures sont proposées, chacune sur 5 niveaux comme le centre de formation : Boutique des supporters (revenu fixe chaque semaine), Station TV (revenu fixe chaque semaine), Salle de musculation (réduit le risque de blessure) et Espace bien-être (réduit la fatigue en match).": "Amplie seu ginásio lugar por lugar para receber mais espectadores (bloco Ampliar o ginásio: cada categoria de lugares tem seu preço por lugar e seu número máximo de lugares), e ajuste o preço do ingresso CATEGORIA POR CATEGORIA: Arquibancada Superior, Tribuna Central, Courtside e Camarotes VIP não têm a mesma capacidade nem a mesma tolerância ao preço. Só os jogos em casa geram renda. O humor dos torcedores influencia a ocupação e a tolerância ao preço. Outras infraestruturas estão disponíveis, cada uma com 5 níveis como o centro de formação: Loja dos torcedores (renda fixa toda semana), Estação de TV (renda fixa toda semana), Sala de musculação (reduz o risco de lesão) e Espaço bem-estar (reduz o cansaço durante o jogo).",
