  "Budget disponible": "Orçamento disponível",
  "Budget du club": "Orçamento do clube",
  "Budget du club et son évolution, masse salariale (joueurs et staff), revenus de la salle, de la boutique et des droits TV, et l'historique des transactions groupé par semaine. Un budget durablement sous le seuil d'alerte finit par mettre tout l'effectif en vente forcée à 1 $ : surveillez la masse salariale.": "Orçamento do clube e sua evolução, folha salarial (jogadores e staff), receitas do ginásio, da loja e dos direitos de TV, e o histórico de transações agrupado por semana. Um orçamento abaixo do limite de alerta por muito tempo acaba colocando todo o elenco em venda forçada a 1 $: fique de olho na folha salarial.",
  "Budget initial : {0}": "Orçamento inicial: {0}",
  "Budget insuffisant pour {0} (coût {1}, budget actuel {2}).": "Orçamento insuficiente para {0} (custo {1}, orçamento atual {2}).",
