  "Budget sous {0} depuis {1} semaines sans redressement : tout l'effectif a été mis en vente forcée à 1 $ (onglet Effectif).": "Orçamento abaixo de {0} há {1} semanas sem recuperação: todo o elenco foi colocado em venda forçada a 1 $ (aba Elenco).",
