  "C’est bientôt l’heure ! Bon match à tous.": "Está quase na hora! Bom jogo a todos.",
  "C'est lui qui fait remonter des prospects de 15 à 17 ans : sans recruteur, aucun jeune ne vous sera proposé.": "É ele quem encontra prospectos de 15 a 17 anos: sem olheiro, nenhum jovem será oferecido a você.",
