  "Cette qualification face à {opponent} en demi-finale doit beaucoup à la réussite autant qu'au mérite, on reste concentrés sur la suite sans s'enflammer.": "Esta classificação contra {opponent} na semifinal deve tanto à sorte quanto ao mérito, seguimos concentrados no que vem sem nos empolgar.",
