  "Changer d'entraîneur": "Trocar de treinador",
  "Changer de recruteur": "Trocar de olheiro",
  "Changer le logo": "Alterar o escudo",
  "Chaque annonce compare le prix à une valeur estimée (Bonne affaire, Prix correct, Au-dessus de sa valeur). Une enchère gagnée s'ajoute immédiatement à votre masse salariale : vérifiez votre budget avant de vous engager.": "Cada anúncio compara o preço com um valor estimado (Bom negócio, Preço justo, Acima do seu valor). Um leilão vencido entra imediatamente na sua folha salarial: verifique seu orçamento antes de se comprometer.",
  "Chaque changement est déjà enregistré automatiquement. « Enregistrer » confirme l'enregistrement auprès du serveur.": "Cada alteração já é salva automaticamente. “Salvar” confirma o salvamento no servidor.",
  "à chaque jour de repos (jour sans match) : soit préparer une nouvelle tactique, soit privilégier la récupération physique de l'équipe.": "a cada dia de descanso (dia sem jogo): ou preparar uma nova tática, ou priorizar a recuperação física da equipe.",
  "Le club choisit": "O clube escolhe",
  "Chaque jour, le club travaille un programme parmi les 13 fondamentaux (tir à 3 points, rebond, défense extérieure...) et un ou plusieurs postes à qui l'appliquer. Cibler un seul poste donne le plein rendement ; l'étendre à toute l'équipe touche plus de joueurs mais dilue l'effet. Le Physique et le Mental évoluent, eux, tout seuls au fil de la carrière, indépendamment de ce programme.": "Todos os dias, o clube trabalha um programa entre os 13 fundamentos (arremesso de 3 pontos, rebote, defesa exterior...) e uma ou várias posições às quais aplicá-lo. Focar em uma só posição dá o rendimento máximo; estendê-lo à equipe toda atinge mais jogadores, mas dilui o efeito. O Físico e o Mental evoluem sozinhos ao longo da carreira, independentemente desse programa.",
  "Chaque match se joue à son heure, que vous le regardiez ou non. Connecté, suivez-le depuis l'onglet": "Cada jogo acontece no seu horário, você assistindo ou não. Conectado, acompanhe-o pela aba",
  "Chaque nom de club doit être une chaîne non vide.": "Cada nome de clube deve ser uma string não vazia.",
  "Chaque prospect affiche une estimation de potentiel (Espoir, Grand espoir ou Prodige) et se signe directement, sans enchère ni négociation, contrairement au marché des transferts.": "Cada prospecto mostra uma estimativa de potencial (Promessa, Grande promessa ou Prodígio) e é contratado diretamente, sem leilão nem negociação, ao contrário do mercado de transferências.",
  "Chaque variation d'ambiance est journalisée ici avec son motif exact : résultat de match, prix du billet, interview de jalon, demande de transfert, signal ou verdict d'objectif de saison.": "Cada variação de ambiente é registrada aqui com seu motivo exato: resultado do jogo, preço do ingresso, entrevista de marco, pedido de transferência, sinal ou veredito da meta da temporada.",
