  "Choisissez exactement 3 systèmes offensifs parmi 10 (Pick & Roll, Transition rapide, Post-up, Isolation...). Chacun modifie la répartition des tirs tentés (intérieur/mi-distance/3 points), les pertes de balle et le rythme.": "Escolha exatamente 3 sistemas ofensivos entre 10 (Pick & Roll, Transição rápida, Post-up, Isolação...). Cada um altera a distribuição dos arremessos tentados (garrafão/meia distância/3 pontos), os desperdícios de bola e o ritmo.",
