  "Connaissance tactique": "Conhecimento tático",
  "Connaissance tactique : chaque option jouée monte de +6 à +12 par match, +4 par jour d'entraînement dessus ; une option délaissée ne baisse qu'à partir du 3e match d'absence (-2, -4, puis -6 au maximum). Le détail est dans le Guide.": "Conhecimento tático: cada opção usada sobe de +6 a +12 por partida, +4 por dia de treino nela; uma opção deixada de lado só começa a cair a partir da 3ª partida sem uso (-2, -4 e depois -6 no máximo). Os detalhes estão no Guia.",
  "Conseil : attaquez la raquette sans crainte, pénétrez et finissez au panier plutôt que de vous contenter du tir extérieur.": "Dica: ataque o garrafão sem medo, infiltre e finalize na cesta em vez de se contentar com o arremesso de fora.",
  "Conseil : envoyez du monde au rebond offensif, les secondes chances seront disponibles.": "Dica: mande gente para o rebote ofensivo, as segundas chances vão aparecer.",
  "Conseil : évitez la finition en force au cercle, privilégiez le tir extérieur ou la passe après pénétration (kick-out) plutôt que le layup contesté.": "Dica: evite forçar a finalização no aro, prefira o arremesso de fora ou o passe após a infiltração (kick-out) em vez da bandeja contestada.",
  "Conseil : forcez la pénétration balle en main et jouez agressif vers le cercle pour provoquer des fautes et aller sur la ligne des lancers francs.": "Dica: force a infiltração com a bola na mão e jogue agressivo rumo ao aro para cavar faltas e ir para a linha de lance livre.",
  "Conseil : ne comptez pas sur les lancers francs, il faudra scorer au jeu plutôt que provoquer la faute.": "Dica: não conte com os lances livres, será preciso pontuar em jogada em vez de cavar a falta.",
  "Conseil : ne surinvestissez pas le rebond offensif, repliez-vous plus tôt pour limiter leur contre-attaque.": "Dica: não invista demais no rebote ofensivo, volte mais cedo para limitar o contra-ataque deles.",
  "Conseil : sécurisez la balle et limitez les passes risquées pour ne pas les lancer en contre-attaque.": "Dica: proteja a bola e limite os passes arriscados para não entregá-los no contra-ataque.",
