  "Contrôlé est le réglage neutre. Agressif conteste mieux les tirs extérieurs réellement pris, mais une fermeture trop appuyée ouvre plus facilement la pénétration : le tireur en profite pour foncer vers le panier plutôt que de tirer.": "Controlado é a configuração neutra. Agressivo contesta melhor os arremessos de fora que realmente são tentados, mas uma recuperação forte demais abre mais facilmente a infiltração: o arremessador aproveita para atacar a cesta em vez de arremessar.",
