  "Jusqu'à 150 000 $": "Até 150.000 $",
  "Jusqu'à 3 affectations poste + focus (empêcher le post-up, coller sur les pénétrations, harceler le tir extérieur, priorité au rebond, couper du ballon). Chaque focus donne un bonus défensif ciblé, avec une petite contrepartie ailleurs pour le défenseur concerné.": "Até 3 atribuições de posição + foco (impedir o post-up, colar nas infiltrações, pressionar o arremesso de fora, prioridade ao rebote, cortar a linha de passe). Cada foco dá um bônus defensivo específico, com uma pequena contrapartida em outro aspecto para o defensor envolvido.",
  "Jusqu'à 300 000 $": "Até 300.000 $",
  "Jusqu'à 50 000 $": "Até 50.000 $",
  "Jusqu'où le joueur peut encore progresser, jamais en chiffre : un palier parmi 10, de Débutant à Générationnel (Prospect, Joueur correct, Solide, Starter, Très bon joueur, Star, All-Star, Superstar). Les jeunes de l'académie n'affichent qu'une estimation : Espoir, Grand espoir ou Prodige.": "Até onde o jogador ainda pode evoluir, nunca em número: um nível entre 10, de Iniciante a Geracional (Prospecto, Jogador razoável, Sólido, Titular, Muito bom jogador, Estrela, All-Star, Superestrela). Os jovens da academia exibem apenas uma estimativa: Promessa, Grande promessa ou Prodígio.",
