  "l'adversaire": "o adversário",
  "L'adversaire ne peut pas aligner un cinq de départ complet : vous gagnerez automatiquement par forfait (20-0) à l'heure prévue.": "O adversário não consegue escalar um quinteto inicial completo: você vencerá automaticamente por W.O. (20-0) no horário previsto.",
  "L’affiche": "O confronto",
  "L'alchimie (40 à 100, visible sur le Tableau de bord et en tête de l'Effectif) mesure la cohésion du groupe. Elle agit sur TOUTE l'équipe en match, de -6 % (vestiaire fracturé) à +6 % (alchimie parfaite). Paliers : Vestiaire fracturé (moins de 48), Tensions dans le groupe (48-59), Cohésion correcte (60-73), Bonne cohésion (74-87), Alchimie parfaite (88 et plus).": "A química (40 a 100, visível no Painel e no topo do Elenco) mede a coesão do grupo. Ela age sobre TODO o time nas partidas, de -6 % (vestiário rachado) a +6 % (química perfeita). Níveis: Vestiário rachado (abaixo de 48), Tensões no grupo (48-59), Entrosamento razoável (60-73), Bom entrosamento (74-87), Química perfeita (88 ou mais).",
  "L'ambiance du club": "O clima do clube",
  "L’attaque tourne à plein régime.": "O ataque está funcionando a todo vapor.",
