  "La feuille de match de l'adversaire est incomplète : vous gagnerez par forfait (20-0) si elle n'est pas réglée avant le coup d'envoi.": "A súmula do adversário está incompleta: você vencerá por W.O. (20-0) se ela não for ajustada antes do salto inicial.",
