  "La liste des jeunes formés dans votre académie qui sont ensuite passés pro : un aperçu de ce que votre filière de formation a déjà produit pour le club.": "A lista dos jovens formados na sua academia que depois se profissionalizaram: um panorama do que a sua base já produziu para o clube.",
  "La plupart des joueurs se situent dans les paliers médians (Starter à All-Star) ; Superstar et Générationnel restent volontairement rares.": "A maioria dos jogadores fica nos níveis intermediários (Titular a All-Star); Superestrela e Geracional são propositalmente raros.",
