  "Le champion est désormais connu, direction l'écran de fin de saison.": "O campeão já é conhecido, rumo à tela de fim de temporada.",
  "Le championnat est lancé": "O campeonato começou",
  "Le classement avant la journée": "A classificação antes da rodada",
  "Le classement s'affichera après les premiers matchs de championnat.": "A classificação vai aparecer após as primeiras partidas do campeonato.",
  "Le classement se départage par victoires puis par différence de points. Il est découpé en zones : places 1 à 4 qualifiées pour les": "A classificação é definida por vitórias e depois por saldo de pontos. Ela é dividida em zonas: posições 1 a 4 classificadas para os",
  "Le classement se départage par victoires puis par différence de points. Places 1 à 4 : play-offs ; 5 et 6 : maintien ; 7 et 8 : barrage ; 9 et 10 : relégation. Ce panneau résume votre position et l'écart avec les places clés.": "A classificação é definida por vitórias e depois por saldo de pontos. Posições 1 a 4: playoffs; 5 e 6: permanência; 7 e 8: repescagem; 9 e 10: rebaixamento. Este painel resume sua posição e a distância para as posições-chave.",
  "Le club est en quasi-faillite (budget : {0}, sous {1} depuis {2} semaine(s)) : tout l'effectif a été mis en vente forcée à 1 $. Direction l'onglet": "O clube está quase falido (orçamento: {0}, abaixo de {1} há {2} semana(s)): todo o elenco foi colocado à venda forçada por 1 $. Vá para a aba",
  "Le club est entre vos mains. Bonne saison, coach.": "O clube está nas suas mãos. Boa temporada, técnico.",
