  "le match précédent": "a partida anterior",
  "Le même Centre de formation que dans l'onglet Salle, mais géré directement ici : agrandissable palier par palier, il accélère la progression automatique de tous vos jeunes tant qu'ils ont moins de 18 ans.": "A mesma Categoria de base da aba Ginásio, mas gerenciada diretamente aqui: ampliável nível por nível, ela acelera a evolução automática de todos os seus jovens enquanto tiverem menos de 18 anos.",
  "Le moteur vise ces minutes et les ajuste seul en cas de blessure, de fautes ou de fatigue. Un poste en automatique garde la rotation habituelle.": "O motor busca esses minutos e os ajusta sozinho em caso de lesão, faltas ou cansaço. Uma posição no automático mantém a rotação habitual.",
  "Le n°1 en fin de saison gagne 1 mois de Premium": "O nº 1 no fim da temporada ganha 1 mês de Premium",
  "Le nom de la ligue doit faire entre 2 et {0} caractères.": "O nome da liga deve ter entre 2 e {0} caracteres.",
  "Le nom de la salle contient des caractères non autorisés.": "O nome do ginásio contém caracteres não permitidos.",
  "Le nom de la salle doit faire entre 3 et {0} caractères.": "O nome do ginásio deve ter entre 3 e {0} caracteres.",
  "Le nom et la capacité de votre salle actuelle, avec un bouton Agrandir pour passer au palier suivant quand vous en avez les moyens (8 paliers en tout, du Petit gymnase à l'Arena nationale).": "O nome e a capacidade do seu ginásio atual, com um botão Ampliar para passar ao nível seguinte quando você tiver recursos (8 níveis no total, do Ginásio pequeno à Arena nacional).",
  "Le numéro {0} est déjà retiré.": "O número {0} já está aposentado.",
  "Le poste de {poste} est désormais pourvu.": "A posição de {poste} agora está preenchida.",
  "Le potentiel indique jusqu'où un joueur peut encore progresser, pas sa qualité du moment. Il ne s'affiche jamais en chiffre : seulement un": "O potencial indica até onde um jogador ainda pode evoluir, não sua qualidade atual. Ele nunca aparece em número: apenas um",
  "Le prix des billets se règle depuis l'onglet Salle, pas ici : ajustez-le pour équilibrer affluence et recettes.": "O preço dos ingressos é definido na aba Ginásio, não aqui: ajuste-o para equilibrar público e receita.",
  "Le roster complet du club en une seule liste, cinq de départ en tête, puis rotation et réserve : poste, potentiel, âge, salaire, forme, motivation et évaluation des derniers matchs. Cliquez sur un nom pour ouvrir la fiche du joueur (caractéristiques, saison, Comparer, Vendre).": "O elenco completo do clube em uma única lista, quinteto inicial primeiro, depois rotação e reservas: posição, potencial, idade, salário, forma, motivação e avaliação das últimas partidas. Clique em um nome para abrir a ficha do jogador (atributos, temporada, Comparar, Vender).",
  "Le serveur a refusé ce nom.": "O servidor recusou este nome.",
