  "Le travail à l'entraînement toute la semaine a payé ce soir, je suis content d'avoir pu répondre présent.": "O trabalho no treino durante a semana toda valeu a pena esta noite, estou feliz por ter correspondido.",
  "Le trigramme doit faire 2 ou 3 lettres (A-Z).": "A sigla deve ter 2 ou 3 letras (A-Z).",
  "Le vrai potentiel d'un jeune reste caché derrière une estimation à 3 paliers jusqu'à sa promotion : la décision comporte donc une part de pari.": "O verdadeiro potencial de um jovem fica escondido atrás de uma estimativa de 3 níveis até sua promoção: a decisão tem, portanto, um quê de aposta.",
