  "Les ligues privées n'existent que dans la ligue partagée entre managers (pas en carrière solo).": "As ligas privadas só existem na liga compartilhada entre managers (não na carreira solo).",
  "Les ligues privées ne sont disponibles que dans la ligue partagée.": "As ligas privadas só estão disponíveis na liga compartilhada.",
  "Les ligues privées sont réservées aux clubs Premium.": "As ligas privadas são exclusivas para clubes Premium.",
  "Les noms de club doivent être uniques.": "Os nomes dos clubes devem ser únicos.",
  "Les ordres de Coupe se préparent comme ceux du championnat, depuis le Calendrier ou le sélecteur de journée de la page Ordres.": "As ordens da Copa são preparadas como as do campeonato, pelo Calendário ou pelo seletor de rodada da aba Ordens.",
  "Les play-offs sont en cours, sur plusieurs jours réels. Revenez pour votre prochain match, ou suivez leur progression ici.": "Os playoffs estão em andamento, ao longo de vários dias reais. Volte para a sua próxima partida ou acompanhe o andamento aqui.",
  "Les play-offs vont commencer.": "Os playoffs vão começar.",
  "Les records s'écriront dès le premier match joué.": "Os recordes começarão a ser escritos a partir da primeira partida disputada.",
  "Le poste d'un joueur suit ses caractéristiques : dès que sa note à un autre poste dépasse nettement celle de son poste actuel, il change de poste (une nouvelle vous prévient). Les salaires (masse salariale visible sur l'onglet": "A posição de um jogador acompanha seus atributos: assim que sua nota em outra posição supera claramente a da posição atual, ele muda de posição (uma notícia avisa você). Os salários (folha salarial visível na aba",
  "Les sponsors reviennent tous les 3 jours. Une meilleure réputation attire de plus grandes marques.": "Os patrocinadores voltam a cada 3 dias. Uma reputação melhor atrai marcas maiores.",
  "Les statistiques de ligue privée ne comptent ni dans les stats de carrière ni dans le classement des joueurs.": "As estatísticas de liga privada não contam nem nas estatísticas de carreira nem no ranking de jogadores.",
