  "MENTAL": "MENTAL",
  "Mental, Endurance, Lancer franc, Puissance, Concentration, Anticipation et Leadership alimentent chacune un mécanisme de match dédié. Le Mental améliore la réussite au tir dans le money time et limite les dégâts d'une mauvaise série. L'Endurance ralentit la fatigue EN MATCH du joueur. Le Lancer franc détermine directement la réussite aux lancers francs, la Concentration l'améliore encore un peu. La Puissance, face à la Force du défenseur, provoque plus de fautes près du panier et permet de marquer malgré le contact. L'Anticipation renforce la pression défensive de toute l'équipe sur les extérieurs. Le Leadership du MEILLEUR joueur du cinq en jeu allège, pour toute l'équipe, le malus d'une mauvaise série de tirs manqués.": "Mental, Resistência, Lance livre, Potência, Concentração, Antecipação e Liderança alimentam, cada um, uma mecânica de jogo específica. O Mental melhora o aproveitamento nos arremessos nos momentos decisivos e limita o estrago de uma sequência ruim. A Resistência retarda o cansaço do jogador DURANTE A PARTIDA. O Lance livre determina diretamente o aproveitamento nos lances livres, e a Concentração o melhora um pouco mais. A Potência, contra a Força do defensor, provoca mais faltas perto da cesta e permite pontuar apesar do contato. A Antecipação reforça a pressão defensiva de todo o time no perímetro. A Liderança do MELHOR jogador do quinteto em quadra reduz, para todo o time, a penalidade de uma sequência ruim de arremessos errados.",
  "mentalAvg": "mentalAvg",
