  "Chaque poste a sa carte sur le terrain : titulaire, remplaçant et réserviste. Les alertes (joueur hors poste, remplaçant plus fort que le titulaire, joueur aligné à deux postes) s'affichent directement sur la carte, et la liste de l'effectif à côté sert à convoquer les 12 joueurs du match.": "Cada posição tem seu card na quadra: titular, reserva e suplente. Os alertas (jogador fora de posição, reserva mais forte que o titular, jogador escalado em duas posições) aparecem direto no card, e a lista do elenco ao lado serve para relacionar os 12 jogadores do jogo.",
