  "Récapitulatif semaine par semaine de votre club : matchs joués et performances individuelles de l'effectif. Naviguez d'une semaine à l'autre avec les flèches en haut de la page. Les finances sont dans l'onglet Économie, l'humeur des supporters dans son propre onglet.": "Resumo semana a semana do seu clube: jogos disputados e desempenhos individuais do elenco. Navegue de uma semana para outra com as setas no topo da página. As finanças ficam na aba Economia, o humor da torcida na sua própria aba.",
