  "Recherche par caractéristiques": "Busca por atributos",
  "Recherche par poste, âge, potentiel, prix (dont \"dans mon budget\") et jusqu'à 5 critères de caractéristiques, avec plusieurs tris (fin d'enchère, note, potentiel, prix, âge). Chaque annonce affiche la note du joueur, ses points forts et un bouton": "Busca por posição, idade, potencial, preço (incluindo \"dentro do meu orçamento\") e até 5 critérios de características, com várias ordenações (fim do leilão, nota, potencial, preço, idade). Cada anúncio mostra a nota do jogador, seus pontos fortes e um botão",
  "avec votre effectif ; on négocie d'abord le contrat avec le joueur, puis on enchérit. Pour vendre l'un de vos joueurs : menu ⋯ de l'Effectif ou bouton Vendre de sa fiche. L'identité de l'enchérisseur en tête reste privée.": "com o seu elenco; primeiro você negocia o contrato com o jogador e depois dá o lance. Para vender um dos seus jogadores: menu ⋯ do Elenco ou botão Vender da ficha dele. A identidade de quem lidera o leilão fica privada.",
