  "Réduit le risque de blessure de vos joueurs. Plusieurs paliers payants au-delà du niveau de base, chacun un cran plus efficace que le précédent.": "Reduz o risco de lesão dos seus jogadores. Vários patamares pagos além do nível básico, cada um um pouco mais eficaz que o anterior.",
