  "Tous les postes": "Todas as posições",
  "Tous vos matchs de la saison, championnat et Coupe, groupés par mois. Les matchs se jouent tout seuls à l'heure prévue (championnat le mardi et le samedi à 20:00, Coupe le jeudi à 20:00) : connectez-vous pour les suivre en direct, ou laissez-les se dérouler sans vous.": "Todos os seus jogos da temporada, campeonato e Copa, agrupados por mês. Os jogos acontecem sozinhos no horário marcado (campeonato às terças e sábados às 20:00, Copa às quintas às 20:00): entre para acompanhá-los ao vivo ou deixe que sejam disputados sem você.",
