  "Trigramme déjà modifié récemment : prochain changement possible dans {0} jour{1}.": "Sigla alterada recentemente: próxima alteração possível em {0} dia.",
  "Trigramme du club": "Sigla do clube",
  "Trigramme enregistré : {0}.": "Sigla salva: {0}.",
  "Quatre catégories de places (Tribune Supérieure, Tribune Centrale, Courtside, Loges VIP), chacune avec son propre prix. Un prix plus élevé rapporte plus par spectateur, mais peut réduire l'affluence si les supporters jugent que ça ne vaut pas le coup.": "Quatro categorias de lugares (Arquibancada Superior, Tribuna Central, Courtside, Camarotes VIP), cada uma com seu próprio preço. Um preço mais alto rende mais por espectador, mas pode reduzir o público se os torcedores acharem que não vale a pena.",
