  "Une séance vidéo a déjà été utilisée aujourd'hui, réessayez demain.": "Uma sessão de vídeo já foi usada hoje, tente novamente amanhã.",
  "Une séance vidéo a déjà été utilisée aujourd'hui.": "Uma sessão de vídeo já foi usada hoje.",
  "Une séance vidéo révèle une partie des caractéristiques de TOUT l'effectif de {0}, définitivement pour la saison. Plus votre analyste vidéo est bon, plus elle en révèle.": "Uma sessão de vídeo revela parte dos atributos de TODO o elenco de {0}, de forma definitiva para a temporada. Quanto melhor o seu analista de vídeo, mais ela revela.",
  "Une séance vidéo révèle une partie des caractéristiques de TOUT l'effectif de {1}, définitivement pour la saison. Plus votre analyste vidéo est bon, plus elle en révèle.": "Uma sessão de vídeo revela parte dos atributos de TODO o elenco de {1}, de forma definitiva para a temporada. Quanto melhor o seu analista de vídeo, mais ela revela.",
