  "Montées et descentes": "Acessos e rebaixamentos",
  ", décidées le lundi d'intersaison et appliquées à la reprise : le champion des play-offs de chaque championnat monte ; en face, le 10e descend, puis le 9e, puis le perdant du barrage (7e contre 8e), autant qu'il y a de championnats ouverts juste en dessous. Une prime de montée est versée au club promu.": ", decididos na segunda-feira da intertemporada e aplicados na volta: o campeão dos playoffs de cada campeonato sobe; em contrapartida, o 10º cai, depois o 9º, depois o perdedor da repescagem (7º contra 8º), tantos quantos forem os campeonatos abertos logo abaixo. Um bônus de acesso é pago ao clube promovido.",
  "(en bas du menu) : choisissez un pays (le vôtre par défaut) pour voir ses divisions ouvertes, son palmarès et les meilleurs joueurs de la saison. Pour afficher un autre championnat ou un club, tapez son nom dans la barre de recherche du haut (« II.2 », « Division III », un nom de club…) : classement, derniers résultats et effectif en lecture seule.": "(no fim do menu): escolha um país (o seu por padrão) para ver as divisões abertas, o histórico de conquistas e os melhores jogadores da temporada. Para exibir outro campeonato ou um clube, digite o nome dele na barra de busca no topo (“II.2”, “Divisão III”, o nome de um clube…): classificação, últimos resultados e elenco somente para consulta.",
