  "Coupe nationale": "Copa nacional",
  "Dans les championnats par pays, c'est la": "Nos campeonatos por país, é a",
  ": tous les clubs du pays (512 au plus), avec des exempts au premier tour pour les divisions les plus hautes si le tableau n'est pas plein. Le club de la division inférieure part avec": ": todos os clubes do país (no máximo 512), com folga na primeira rodada para as divisões mais altas se a chave não estiver cheia. O clube da divisão inferior começa com",
  "+7 points par division d'écart": "+7 pontos por divisão de diferença",
  "(au plus +21), déjà au tableau d'affichage. Un adversaire d'un autre championnat se prépare comme les autres (Ordres, scouting) et sa fiche s'ouvre dans Planète Hoop. Chaque match de Coupe gagné rapporte une prime, de 50 000 $ aux premiers tours à 400 000 $ pour la finale. À l'intersaison, la": "(no máximo +21), já no placar. Um adversário de outro campeonato é preparado como os outros (Ordens, scouting) e a ficha dele abre no Planeta Hoop. Cada jogo de Copa vencido rende um bônus, de 50 000 $ nas primeiras rodadas a 400 000 $ na final. Na intertemporada, a",
  "oppose le samedi à 20:00 le champion de Division I au vainqueur de la Coupe (ou au finaliste si c'est le même club), en direct et avec le même handicap : 200 000 $ pour le vainqueur.": "coloca frente a frente, no sábado às 20:00, o campeão da Divisão I e o vencedor da Copa (ou o finalista, se for o mesmo clube), ao vivo e com a mesma vantagem: 200 000 $ para o vencedor.",
  "Coupe nationale · {0} · saison {1} : tous les clubs du pays, un tour chaque jeudi. Le club de division inférieure part avec": "Copa nacional · {0} · temporada {1}: todos os clubes do país, uma rodada toda quinta-feira. O clube de divisão inferior começa com",
  "(au plus +21), compris dans les scores.": "(no máximo +21), incluídos nos placares.",
