  "Barrage (7e contre 8e) : {0} {1}-{2} {3}. Le club pourra être relégué si le championnat du dessous est ouvert.": "Repescagem (7º contra 8º): {0} {1}-{2} {3}. O clube poderá ser rebaixado se o campeonato de baixo estiver aberto.",
