  "La note de chacun de vos joueurs semaine après semaine, sur sa fiche.": "A nota de cada um dos seus jogadores semana após semana, na ficha dele.",
  "True shooting, réussite effective, stats par 36 minutes, +/- de la saison, et export du tableau en CSV (onglet Statistiques).": "True shooting, aproveitamento efetivo, estatísticas por 36 minutos, +/- da temporada e exportação da tabela em CSV (aba Estatísticas).",
  "Revoir le direct": "Rever a transmissão",
  "Rejouer le direct de vos matchs déjà joués, depuis leur feuille de statistiques (60 derniers matchs du championnat).": "Reveja a transmissão ao vivo dos seus jogos já disputados, pela súmula (últimos 60 jogos do campeonato).",
  "Une notification de votre navigateur (ou de l'application installée sur votre téléphone) quand votre match commence, qu'un joueur se blesse ou qu'une de vos enchères (joueur ou staff) se termine.": "Uma notificação do seu navegador (ou do app instalado no seu celular) quando seu jogo começa, quando um jogador se lesiona ou quando um dos seus leilões (jogador ou comissão técnica) termina.",
