  "Ce navigateur ne gère pas les notifications. Sur iPhone, ajoute d'abord le jeu à l'écran d'accueil (Partager → Sur l'écran d'accueil).": "Este navegador não suporta notificações. No iPhone, primeiro adicione o jogo à tela de início (Compartilhar → Adicionar à Tela de Início).",
  "Coup d'envoi de vos matchs, blessures, arrivées et départs, et vos enchères (joueurs et staff) : fin dans moins d'une heure, puis remportée ou perdue.": "Início dos seus jogos, lesões, chegadas e saídas, e seus leilões (jogadores e comissão técnica): menos de uma hora para terminar, depois vencido ou perdido.",
