  "Longue absence": "Ausência prolongada",
  ": sans aucune visite pendant 45 jours, votre club est confié à l'IA (effectif, nom et palmarès conservés). Reconnectez-vous à votre compte pour le récupérer, s'il n'a pas été repris entre-temps par un autre manager ; sinon un nouveau club vous est attribué.": ": sem nenhuma visita por 45 dias, seu clube é entregue à IA (elenco, nome e histórico de conquistas mantidos). Entre de novo na sua conta para recuperá-lo, caso ele não tenha sido assumido por outro manager nesse meio-tempo; caso contrário, um novo clube é atribuído a você.",
  "Bon retour à {0} !": "Bem-vindo de volta ao {0}!",
  "Pendant votre absence, le club a été géré par l'IA. Vérifiez votre effectif, vos ordres et votre budget.": "Durante sua ausência, o clube foi gerenciado pela IA. Confira seu elenco, suas ordens e seu orçamento.",
  "Contre un club d'un autre championnat": "Contra um clube de outro campeonato",
  ", même d'un autre pays : tapez son nom dans la recherche d'adversaire, les clubs du monde entier apparaissent sous ceux de votre ligue (drapeau et division). Mêmes règles : jour de repos des deux clubs, heure de Paris, invitation à accepter contre un manager (il est prévenu dans son fil d'actualité).": ", até de outro país: digite o nome dele na busca de adversário, os clubes do mundo inteiro aparecem abaixo dos da sua liga (bandeira e divisão). Mesmas regras: dia de descanso dos dois clubes, horário de Paris, convite a ser aceito quando for contra um manager (ele é avisado no feed de notícias).",
  "Club d'un autre championnat ({0}) : l'amical se joue à la même heure (Paris) pour les deux clubs.": "Clube de outro campeonato ({0}): o amistoso é disputado no mesmo horário (Paris) para os dois clubes.",
  "Autre championnat": "Outro campeonato",
  "Un des deux clubs a changé de championnat.": "Um dos dois clubes mudou de campeonato.",
  "Adversaire du même championnat : passez par la liste habituelle.": "Adversário do mesmo campeonato: use a lista habitual.",
  "Monde entier": "Mundo inteiro",
  "Mon pays": "Meu país",
  "Mon championnat": "Meu campeonato",
  "Marché mondial": "Mercado mundial",
  ": les annonces de tous les championnats, dans tous les pays, apparaissent aussi (drapeau et division du vendeur sur la carte ; filtre « Monde entier », « Mon championnat » ou le pays de votre choix, avec une recherche). On y enchérit de la même façon ; le joueur rejoint votre club à la clôture de l'enchère. Les annonces des autres championnats se mettent à jour toutes les quelques minutes : si quelqu'un a surenchéri entre-temps, votre enchère est refusée et le prix actualisé.": ": os anúncios de todos os campeonatos, em todos os países, também aparecem (bandeira e divisão do vendedor no cartão; filtro “Mundo inteiro”, “Meu campeonato” ou o país que você quiser, com uma busca). Os lances funcionam do mesmo jeito; o jogador chega ao seu clube quando o leilão termina. Os anúncios dos outros campeonatos são atualizados a cada poucos minutos: se alguém cobriu seu lance nesse meio-tempo, seu lance é recusado e o preço atualizado.",
