  "À la fin de la saison régulière, la ligue décerne ses": "No fim da temporada regular, a liga entrega seus",
  "récompenses": "prêmios",
  ": MVP, 5 majeur (un joueur par poste), meilleur jeune (21 ans ou moins), 6e homme (un joueur surtout remplaçant) et meilleur défenseur, puis le": ": MVP, quinteto ideal (um jogador por posição), melhor jovem (21 anos ou menos), sexto homem (um jogador que sai principalmente do banco) e melhor defensor, e depois o",
  "(dans l'équipe championne) après la finale. Elles se calculent sur la saison régulière, pour les joueurs qui ont disputé au moins 40 % des journées, et s'affichent dans l'onglet Ligue.": "(do time campeão) após a final. Eles são calculados com base na temporada regular, para os jogadores que disputaram pelo menos 40 % das rodadas, e aparecem na aba Liga.",
  "À mi-saison, le dimanche à 20h, les 10 meilleurs joueurs du pays affrontent les 10 meilleurs étrangers lors du": "No meio da temporada, no domingo às 20h, os 10 melhores jogadores do país enfrentam os 10 melhores estrangeiros no",
  ", un match d'exhibition sans effet sur le classement ni sur la forme. La fiche de chaque joueur montre sa nationalité et sa": ", um jogo de exibição sem efeito na classificação nem na forma. A ficha de cada jogador mostra sua nacionalidade e sua",
