  "On y trouve aussi vos": "Lá você também encontra suas",
  "succès": "conquistas",
  "de manager (première victoire, séries, titres, salle pleine, jeune formé au club devenu titulaire...), avec une barre de progression pour ceux qui restent à débloquer. Les autres managers les voient, avec votre bilan et vos titres, dans le profil affiché sur la fiche de votre club.": "de manager (primeira vitória, sequências, títulos, ginásio lotado, jovem formado no clube que virou titular...), com uma barra de progresso para as que ainda faltam desbloquear. Os outros managers as veem, junto com sua campanha e seus títulos, no perfil exibido na página do seu clube.",
