  "Recruter au marché du staff": "Contratar no mercado da equipa técnica",
  "Le staff se recrute aux enchères, dans l'onglet Marché, rubrique Staff. Chaque candidat (niveau 1 à 5) reste en vente 1 jour réel et les autres clubs peuvent surenchérir jusqu'au bout. Votre mise n'est pas un paiement unique : c'est le salaire hebdomadaire de départ du membre du staff, qui augmente ensuite un peu chaque semaine.": "A equipa técnica contrata-se em leilão, no separador Mercado, secção Staff. Cada candidato (nível 1 a 5) fica à venda 1 dia real e os outros clubes podem cobrir a oferta até ao fim. A tua oferta não é um pagamento único: é o salário semanal inicial do membro do staff, que depois sobe um pouco todas as semanas.",
  "Gagner une enchère remplace votre membre du staff actuel au même poste, sans indemnité. Le montant de vos enchères en tête est réservé sur votre budget jusqu'à la fin de la vente.": "Ganhar um leilão substitui o membro do staff atual no mesmo cargo, sem indemnização. O valor das tuas ofertas na frente fica reservado no orçamento até ao fim da venda.",
