  "{0} refuse votre offre et perd en motivation. Sa demande augmente ; vous pourrez lui faire une nouvelle offre la semaine prochaine.": "{0} recusa a sua proposta e perde motivação. O pedido dele sobe; poderá fazer-lhe uma nova proposta na próxima semana.",
