  "Ces ordres valent pour tous vos matchs de ligue privée à venir, jamais pour les matchs officiels. Sans ordres enregistrés, la ligue privée se joue avec les ordres actuels du club.": "Estas ordens valem para todos os seus próximos jogos de liga privada, nunca para os jogos oficiais. Sem ordens salvas, a liga privada é jogada com as ordens atuais do clube.",
