  "Plus vos supporters sont heureux, plus ils achètent. Les maillots les plus vendus sont ceux de vos meilleurs joueurs.": "Quanto mais felizes os teus adeptos, mais compram. As camisolas mais vendidas são as dos teus melhores jogadores.",
