  "conseils": "dicas",
  "Tactique × {0}": "Tática × {0}",
  "Récupération × {0}": "Recuperação × {0}",
  "Physique × {0}": "Físico × {0}",
  "Blessé à l'entraînement": "Lesionado no treino",
  "{0} n'a joué que {1} min cette semaine sur {2} : son plan ne compte qu'à {3} %.": "{0} jogou só {1} min nesta semana de {2}: o plano dele conta só {3}%.",
  "Forme moyenne de l'équipe": "Forma média da equipe",
  "Plans individuels.": "Planos individuais.",
  "Chaque place de plan associe un joueur à un programme parmi les 13 fondamentaux (tir, passe, défense, etc.), quel que soit son poste. Le nombre de places dépend de l'entraîneur : 3 aux niveaux 1 et 2, 4 aux niveaux 3 et 4, 5 au niveau 5. Sans entraîneur, aucun fondamental n'est travaillé. L'entraînement se déclenche le lundi à 6h, heure de Paris.": "Cada vaga de plano associa um jogador a um programa entre os 13 fundamentos (arremesso, passe, defesa etc.), qualquer que seja a posição dele. O número de vagas depende do treinador: 3 nos níveis 1 e 2, 4 nos níveis 3 e 4, 5 no nível 5. Sem treinador, nenhum fundamento é treinado. O treino é aplicado na segunda-feira às 6h, horário de Paris.",
  "Rendement.": "Rendimento.",
  "Un joueur en plan doit avoir joué 30 minutes dans la semaine (championnat, Coupe, play-offs et amicaux) pour un plein rendement, moins s'il a peu joué. L'âge (les jeunes apprennent plus vite), le gabarit, le niveau de l'entraîneur et l'intensité de la semaine font varier le rendement, affiché en % pour chaque joueur. Le poste n'a plus d'effet.": "Um jogador com plano precisa ter jogado 30 minutos na semana (liga, Copa, playoffs e amistosos) para o rendimento total, menos se jogou pouco. Idade (os jovens aprendem mais rápido), biotipo, nível do treinador e intensidade da semana fazem o rendimento variar, exibido em % para cada jogador. A posição não importa mais.",
  "Intensité.": "Intensidade.",
  "Légère : progression plus lente, meilleure récupération. Normale. Intense : progression plus rapide, mais forme en baisse et petit risque de blessure pour les joueurs en plan.": "Leve: progresso mais lento, melhor recuperação. Normal. Intensa: progresso mais rápido, mas forma em queda e pequeno risco de lesão para os jogadores com plano.",
  "Plafond.": "Teto.",
  "Chaque joueur a une marge de progression propre ; quand elle se réduit, la progression ralentit peu à peu, sans s'arrêter net. Un bon entraîneur repousse ce plafond. Quand un joueur ne progresse plus, le bilan du lundi propose un autre programme (bouton Appliquer).": "Cada jogador tem sua própria margem de evolução; quando ela diminui, o progresso desacelera aos poucos, sem parar de vez. Um bom treinador eleva esse teto. Quando um jogador para de evoluir, o balanço de segunda-feira sugere outro programa (botão Aplicar).",
  "Spécialités de l'entraîneur.": "Especialidades do treinador.",
  "Attaque ou Défense : programmes de cette famille plus efficaces. Physique : jours Physique plus efficaces. Jeunes : joueurs de 21 ans et moins, et académie, plus efficaces.": "Ataque ou Defesa: programas dessa família mais eficazes. Físico: dias de Físico mais eficazes. Jovens: jogadores de 21 anos ou menos, e a base, treinam melhor.",
  "Collectif.": "Coletivo.",
  "Chaque jour sans match officiel, choisissez Tactique (un aspect précis : une priorité offensive, une défense ou un rythme ; plus il est neuf, plus il progresse vite), Récupération (forme en hausse pour tout l'effectif) ou Physique (petit gain physique, surtout pour les jeunes). Un jour d'amical, la tactique n'est pas possible, mais les joueurs non retenus pour l'amical peuvent récupérer ou faire du physique.": "Em cada dia sem jogo oficial, escolha Tática (um aspecto preciso: uma prioridade ofensiva, uma defesa ou um ritmo; quanto mais novo, mais rápido evolui), Recuperação (forma em alta para todo o elenco) ou Físico (pequeno ganho físico, sobretudo para os jovens). Em dia de amistoso não é possível treinar tática, mas os jogadores não convocados podem se recuperar ou fazer físico.",
  "Mental et parrainage.": "Mental e mentoria.",
  "Le mental progresse en partie tout seul, en partie avec les minutes jouées dans la semaine. Un jeune (22 ans au plus) associé à un vétéran (29 ans au moins) du même poste progresse plus vite au mental (2 parrainages au plus).": "O mental evolui em parte sozinho, em parte com os minutos jogados na semana. Um jovem (no máximo 22 anos) associado a um veterano (no mínimo 29 anos) da mesma posição evolui mais rápido no mental (no máximo 2 mentorias).",
  "Chaque semaine (le lundi à 6h), vos joueurs en plan individuel travaillent le programme choisi pour eux parmi les 13 fondamentaux. Le nombre de places dépend de votre entraîneur (3 à 5) : sans entraîneur, pas de travail des fondamentaux. Le Physique et le Mental évoluent tout seuls, le Mental aussi avec les minutes jouées.": "Toda semana (segunda-feira às 6h), seus jogadores com plano individual treinam o programa escolhido para eles entre os 13 fundamentos. O número de vagas depende do seu treinador (3 a 5): sem treinador, nada de treino de fundamentos. O Físico e o Mental evoluem sozinhos, o Mental também com os minutos jogados.",
  "Un joueur en plan doit jouer 30 minutes dans la semaine (championnat, Coupe, play-offs et amicaux) pour un plein rendement ; le poste n'a plus d'importance.": "Um jogador com plano precisa jogar 30 minutos na semana (liga, Copa, playoffs e amistosos) para o rendimento total; a posição não importa mais.",
  "Chaque jour sans match, choisissez Tactique (un aspect précis), Récupération (forme +15) ou Physique (petit gain physique, surtout pour les jeunes). Un jour d'amical, les joueurs non retenus peuvent récupérer ou faire du physique.": "Em cada dia sem jogo, escolha Tática (um aspecto preciso), Recuperação (forma +15) ou Físico (pequeno ganho físico, sobretudo para os jovens). Em dia de amistoso, os jogadores não convocados podem se recuperar ou fazer físico.",
  "Une tactique neuve s'apprend vite (+12 par jour à 40), une tactique déjà maîtrisée beaucoup moins (+4 par jour à 95). Le détail est dans le Guide.": "Uma tática nova se aprende rápido (+12 por dia a 40), uma já dominada muito menos (+4 por dia a 95). Os detalhes estão no Guia.",
  // Entraînement v2 (retour utilisateur 2026-10-01).
  "+{0}/jour": "+{0}/dia",
  "Votre équipe maîtrise plus ou moins chaque option tactique : une jauge par priorité offensive, par défense et par rythme (visible dans le menu \"Aspect travaillé\" de l'Entraînement). La maîtrise des options que vous jouez agit sur toute l'équipe en match, jusqu'à +/-8 %, en plus de l'alchimie.": "Sua equipe domina mais ou menos cada opção tática: um medidor por prioridade ofensiva, por defesa e por ritmo (visível no menu \"Aspecto trabalhado\" do Treino). O domínio das opções que você usa age sobre toda a equipe em jogo, até +/-8 %, além da química.",
  "sur cette option la fait monter à chaque jour de repos écoulé, selon son niveau : +12 par jour à 40, +9 à 60, +6 à 80, +4 à 95 (jamais un jour d'amical). Un": "nessa opção a faz subir a cada dia de descanso concluído, conforme o nível: +12 por dia a 40, +9 a 60, +6 a 80, +4 a 95 (nunca em dia de amistoso). Um",
